12	// This file guards QueryTxs against a main-chain reorg that makes the chain
13	// shorter while a paginated query is in flight. A first page issued at that
14	// instant must answer from ONE complete main chain — either the old chain or
15	// the new one: the pinned upper height, the whole-range statistics, every
16	// returned record, and the continuation cursor must all describe that same
17	// branch. Once the first page has pinned its range, a continuation either
18	// still sees the complete chain the first page saw (statistics and pinned
19	// height identical) or fails with ErrQueryChanged and a fully zeroed result;
20	// it can never stitch two branches together.
21	//
22	// The scenario (no filter, To left at zero so the first page pins the tip):
23	//
24	//	Retained ancestor (both chains):
25	//	  h1 parent g  txs [x, x] // same id twice in one block: two occurrences
26	//	  h2 parent h1 txs [y]
27	//	Old branch, tip 5:
28	//	  h3 parent h2 txs [a, c]
29	//	  h4 parent h3 txs [d, d]    // duplicate inside one block; block counts once
30	//	  h5 parent h4 txs [e, f, g]
31	//	New shorter branch, tip 4 (replaces h3..h5, rooted at the retained h2):
32	//	  j3 parent h2 txs [p, q]
33	//	  j4 parent j3 txs [r, s, r] // different multiplicity; h5 vanishes
34	//
35	// Old-chain answer (range 1..5): 10 occurrences over 5 blocks, tip 5.
36	// New-chain answer (range 1..4):  8 occurrences over 4 blocks, tip 4.
37	//
38	// The suffix transaction sets are disjoint ({a,c,d,e,f,g} vs {p,q,r,s}) and
39	// every suffix hash differs, so the two complete answers are observably
40	// different not just in their counts but in every record above height 2. A
41	// page that happens to stay ordered (e.g. one new-chain hit followed by one
42	// old-chain hit at consecutive positions) is still a torn answer and must be
43	// rejected by classifyTxPage.
44	
45	func queryRetainedBlocks() []Block {
46		return []Block{
47			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"x", "x"}},
48			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"y"}},
49		}
50	}
51	
52	func queryOldSuffixBlocks() []Block {
53		return []Block{
54			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a", "c"}},
55			{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"d", "d"}},
56			{Height: 5, Hash: "h5", Parent: "h4", Txs: []string{"e", "f", "g"}},
57		}
58	}
59	
60	func queryNewShortBranch() []Block {
61		return []Block{
62			{Height: 3, Hash: "j3", Parent: "h2", Txs: []string{"p", "q"}},
63			{Height: 4, Hash: "j4", Parent: "j3", Txs: []string{"r", "s", "r"}},
64		}
65	}
66	
67	func queryOldChainBlocks() []Block {
68		chain := append([]Block{}, queryRetainedBlocks()...)
69		return append(chain, queryOldSuffixBlocks()...)
70	}
71	
72	func queryNewChainBlocks() []Block {
73		chain := append([]Block{}, queryRetainedBlocks()...)
74		return append(chain, queryNewShortBranch()...)
75	}
76	
77	func buildQueryOldChain(t *testing.T) *Index {
78		t.Helper()
79		index := New()
80		for _, b := range queryOldChainBlocks() {
81			if err := index.Append(b); err != nil {
82				t.Fatalf("setup append at %d: %v", b.Height, err)
83			}
84		}
85		return index
86	}
87	
88	// referenceTxHits is an independent oracle: it derives the complete ordered
89	// occurrence list from an explicitly supplied chain, not from the Index under
90	// test, so a shared QueryTxs bug cannot make an expectation match itself.
91	func referenceTxHits(chain []Block) []TxHit {
92		hits := []TxHit{}
93		for _, block := range chain {
94			for position, tx := range block.Txs {
95				hits = append(hits, TxHit{
96					Height:    block.Height,
97					BlockHash: block.Hash,
98					TxID:      tx,
99					Position:  position,
100				})
101			}
102		}
103		return hits
104	}
105	
106	func referenceMatchedBlocks(chain []Block) int64 {
107		var blocks int64
108		for _, block := range chain {
109			if len(block.Txs) > 0 {
110				blocks++
111			}
112		}
113		return blocks
114	}
115	
116	// referenceTxPage is one page of the complete answer for chain (heights
117	// 1..len(chain)) sliced at offset, with the whole-range statistics the page
118	// must carry. The continuation cursor is deliberately excluded: it is opaque
119	// and is validated separately by actually following it.
120	func referenceTxPage(chain []Block, pageSize int, offset int64) TxPage {
121		full := referenceTxHits(chain)
122		rest := full[offset:]
123		end := pageSize
124		if end > len(rest) {
125			end = len(rest)
126		}
127		return TxPage{
128			Hits:          append([]TxHit{}, rest[:end]...),
129			TotalMatches:  int64(len(full)),
130			MatchedBlocks: referenceMatchedBlocks(chain),
131			ToHeight:      int64(len(chain)),
132		}
133	}
134	
135	// Hand-derived key records, so the guarantee rests on the literal
136	// transactions of each branch rather than on oracle-vs-DeepEqual alone.
137	func literalOldFirstPage() TxPage {
138		return TxPage{
139			Hits: []TxHit{
140				{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
141				{Height: 1, BlockHash: "h1", TxID: "x", Position: 1},
142				{Height: 2, BlockHash: "h2", TxID: "y", Position: 0},
143			},
144			TotalMatches:  10,
145			MatchedBlocks: 5,
146			ToHeight:      5,
147		}
148	}
149	
150	func literalNewFirstPage() TxPage {
151		page := literalOldFirstPage()
152		page.TotalMatches = 8
153		page.MatchedBlocks = 4
154		page.ToHeight = 4
155		return page
156	}
