158	// The counting and ordering semantics the regression rests on, asserted for
159	// each chain and cross-checked against the live index before and after the
160	// reorg.
161	func TestReorgQueryFixtureSemanticsOnBothChains(t *testing.T) {
162		oldChain := queryOldChainBlocks()
163		newChain := queryNewChainBlocks()
164	
165		// Setup invariant: suffix identifier sets must be disjoint and every
166		// suffix hash must differ, otherwise a mixed page could be
167		// indistinguishable by content.
168		oldIDs := map[string]struct{}{}
169		for _, b := range oldChain[2:] {
170			for _, tx := range b.Txs {
171				oldIDs[tx] = struct{}{}
172			}
173		}
174		for _, b := range newChain[2:] {
175			for _, tx := range b.Txs {
176				if _, conflict := oldIDs[tx]; conflict {
177					t.Fatalf("setup invariant broken: new-branch tx %q also exists on the old suffix", tx)
178				}
179			}
180		}
181	
182		oldHits := referenceTxHits(oldChain)
183		wantOld := []TxHit{
184			{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
185			{Height: 1, BlockHash: "h1", TxID: "x", Position: 1},
186			{Height: 4, BlockHash: "h4", TxID: "d", Position: 0},
187			{Height: 4, BlockHash: "h4", TxID: "d", Position: 1},
188			{Height: 5, BlockHash: "h5", TxID: "g", Position: 2},
189		}
190		for _, want := range wantOld {
191			if !containsHit(oldHits, want) {
192				t.Fatalf("old chain misses literal occurrence %+v in %v", want, oldHits)
193			}
194		}
195		if len(oldHits) != 10 || referenceMatchedBlocks(oldChain) != 5 {
196			t.Fatalf("old chain: hits=%d blocks=%d, want 10/5", len(oldHits), referenceMatchedBlocks(oldChain))
197		}
198		newHits := referenceTxHits(newChain)
199		if len(newHits) != 8 || referenceMatchedBlocks(newChain) != 4 {
200			t.Fatalf("new chain: hits=%d blocks=%d, want 8/4", len(newHits), referenceMatchedBlocks(newChain))
201		}
202		// h4's two d's are one block; j4's two r's are one block; removed
203		// height 5 is simply absent.
204		for _, gone := range []TxHit{
205			{Height: 5, BlockHash: "h5", TxID: "e", Position: 0},
206			{Height: 4, BlockHash: "h4", TxID: "d", Position: 0},
207		} {
208			if containsHit(newHits, gone) {
209				t.Fatalf("new chain must not carry %+v", gone)
210			}
211		}
212		if !containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "r", Position: 0}) ||
213			!containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "r", Position: 2}) {
214			t.Fatalf("new chain must keep both r occurrences: %v", newHits)
215		}
216		// Every occurrence list is ordered by height then position.
217		requireOrdered(t, oldHits)
218		requireOrdered(t, newHits)
219	
220		// The oracle must match the live index on both complete chain states.
221		index := buildQueryOldChain(t)
222		live, err := index.QueryTxs(TxQuery{})
223		if err != nil {
224			t.Fatal(err)
225		}
226		if !reflect.DeepEqual(live.Hits, oldHits) || live.TotalMatches != 10 || live.MatchedBlocks != 5 || live.ToHeight != 5 {
227			t.Fatalf("live old-chain query=%+v, want 10/5/tip5", live)
228		}
229		dropped, err := index.Reorg(queryNewShortBranch())
230		if err != nil {
231			t.Fatalf("shortening reorg refused: %v", err)
232		}
233		if want := []int64{3, 4, 5}; !reflect.DeepEqual(dropped, want) {
234			t.Fatalf("dropped=%v, want %v", dropped, want)
235		}
236		if index.Tip != 4 {
237			t.Fatalf("tip=%d, want shortened tip 4", index.Tip)
238		}
239		if _, ok := index.Blocks[5]; ok {
240			t.Fatal("height 5 still present after shortening reorg")
241		}
242		if _, ok := index.ByHash["h5"]; ok {
243			t.Fatal("removed hash h5 still indexed")
244		}
245		live, err = index.QueryTxs(TxQuery{})
246		if err != nil {
247			t.Fatal(err)
248		}
249		if !reflect.DeepEqual(live.Hits, newHits) || live.TotalMatches != 8 || live.MatchedBlocks != 4 || live.ToHeight != 4 {
250			t.Fatalf("live new-chain query=%+v, want 8/4/tip4", live)
251		}
252	}
253	
254	func containsHit(hits []TxHit, want TxHit) bool {
255		for _, hit := range hits {
256			if hit == want {
257				return true
258			}
259		}
260		return false
261	}
262	
263	func requireOrdered(t *testing.T, hits []TxHit) {
264		t.Helper()
265		for i := 1; i < len(hits); i++ {
266			prev, cur := hits[i-1], hits[i]
267			if cur.Height < prev.Height || (cur.Height == prev.Height && cur.Position <= prev.Position) {
268				t.Fatalf("hits not ordered at %d: %+v after %+v", i, cur, prev)
269			}
270		}
271	}
272	
273	// classifyTxPage accepts got only when its visible contents are the first-page
274	// view of exactly one chain. The opaque NextCursor is not part of this view;
275	// callers validate it by following it. Record provenance is checked against
276	// the COMPLETE branch hit lists, not just the records on the reference page,
277	// so a stitched page drawn from later heights is still exposed. It does NOT
278	// treat "hit count equals TotalMatches" as sufficient: an ordered, correctly
279	// counted stitched page still carries records from both branches.
280	func classifyTxPage(got, oldRef, newRef TxPage, oldAllHits, newAllHits []TxHit) error {
281		type view struct {
282			Hits          []TxHit
283			TotalMatches  int64
284			MatchedBlocks int64
285			ToHeight      int64
286		}
287		of := func(p TxPage) view {
288			return view{Hits: p.Hits, TotalMatches: p.TotalMatches, MatchedBlocks: p.MatchedBlocks, ToHeight: p.ToHeight}
289		}
290		g, o, n := of(got), of(oldRef), of(newRef)
291		if reflect.DeepEqual(g, o) || reflect.DeepEqual(g, n) {
292			return nil
293		}
294	
295		var report strings.Builder
296		fmt.Fprintln(&report, "QueryTxs page does not match one complete main chain:")
297		tags := map[string]bool{}
298		tag := func(name string, gotV, oldV, newV any) {
299			matchesOld := reflect.DeepEqual(gotV, oldV)
300			matchesNew := reflect.DeepEqual(gotV, newV)
301			label := "neither"
302			switch {
303			case matchesOld && matchesNew:
304				label = "both"
305			case matchesOld:
306				label = "OLD"
307				tags["old"] = true
308			case matchesNew:
309				label = "NEW"
310				tags["new"] = true
311			}
312			fmt.Fprintf(&report, "  %-15s got=%v old=%v new=%v -> %s\n", name, gotV, oldV, newV, label)
313		}
314		tag("ToHeight", g.ToHeight, o.ToHeight, n.ToHeight)
315		tag("TotalMatches", g.TotalMatches, o.TotalMatches, n.TotalMatches)
316		tag("MatchedBlocks", g.MatchedBlocks, o.MatchedBlocks, n.MatchedBlocks)
317	
318		// Record-level provenance: each hit must be explainable by the same chain
319		// at the same page offset. This is what rejects an ordered-looking page
320		// that interleaves two branches.
321		oldByKey := map[TxHit]bool{}
322		newByKey := map[TxHit]bool{}
323		for _, h := range oldAllHits {
324			oldByKey[h] = true
325		}
326		for _, h := range newAllHits {
327			newByKey[h] = true
328		}
329		var inOld, inNew, inNeither int
330		var onlyOld, onlyNew int
331		ordered := true
332		for i, h := range g.Hits {
333			co, cn := oldByKey[h], newByKey[h]
334			if co {
335				inOld++
336			}
337			if cn {
338				inNew++
339			}
340			if co && !cn {
341				onlyOld++
342			}
343			if cn && !co {
344				onlyNew++
345			}
346			if !co && !cn {
347				inNeither++
348			}
349			if i > 0 {
350				prev := g.Hits[i-1]
351				if h.Height < prev.Height || (h.Height == prev.Height && h.Position <= prev.Position) {
352					ordered = false
353				}
354			}
355			if h.Height > g.ToHeight {
356				fmt.Fprintf(&report, "  hit above pinned ToHeight %d: %+v\n", g.ToHeight, h)
357			}
358		}
359		fmt.Fprintf(&report, "  Hits provenance  on-old=%d on-new=%d only-old=%d only-new=%d on-neither=%d (ordered=%v)\n",
360			inOld, inNew, onlyOld, onlyNew, inNeither, ordered)
361		// A record that belongs to exactly one branch tags that branch; shared
362		// ancestor records tag neither.
363		if onlyOld > 0 {
364			tags["old"] = true
365		}
366		if onlyNew > 0 {
367			tags["new"] = true
368		}
369		switch {
370		case tags["old"] && tags["new"]:
371			fmt.Fprintf(&report, "  => MIXED: stats and records come from both the old and the new chain; one page must reflect a single main chain")
372		case inNeither > 0:
373			fmt.Fprintf(&report, "  => CORRUPT: records exist on neither chain")
374		default:
375			fmt.Fprintf(&report, "  => CORRUPT: matches neither the old nor the new chain")
376		}
377		return errors.New(report.String())
378	}
379	
380	// The classifier must accept both complete answers and reject ordered-looking
381	// mixtures and plain corruption.
382	func TestClassifyTxPageRejectsMixedAndCorruptPages(t *testing.T) {
383		oldRef := literalOldFirstPage()
384		newRef := literalNewFirstPage()
385		oldAll := referenceTxHits(queryOldChainBlocks())
386		newAll := referenceTxHits(queryNewChainBlocks())
387		classify := func(page TxPage) error { return classifyTxPage(page, oldRef, newRef, oldAll, newAll) }
388		if err := classify(oldRef); err != nil {
389			t.Fatalf("pure old page rejected: %v", err)
390		}
391		if err := classify(newRef); err != nil {
392			t.Fatalf("pure new page rejected: %v", err)
393		}
394	
395		// Mixture 1: shared first-page records (identical on both chains), but
396		// new-chain counts under the OLD tip height. Hit count still equals the
397		// total on both chains, so a count-equality check would accept it.
398		mixed1 := newRef
399		mixed1.ToHeight = oldRef.ToHeight
400		if int64(len(mixed1.Hits)) != 3 || mixed1.TotalMatches != 8 {
401			t.Fatal("test setup: mixed1 counts are meant to look internally consistent")
402		}
403		if err := classify(mixed1); err == nil {
404			t.Fatal("new-chain counts under the old tip height were accepted")
405		} else if !strings.Contains(err.Error(), "MIXED") {
406			t.Fatalf("mixed1 not reported as MIXED:\n%v", err)
407		}
408	
409		// Mixture 2: old-chain counts and records under the NEW shortened tip
410		// height — claims tip 4 while still counting removed height 5.
411		mixed2 := oldRef
412		mixed2.ToHeight = newRef.ToHeight
413		if err := classify(mixed2); err == nil {
414			t.Fatal("old-chain counts under the new tip height were accepted")
415		} else if !strings.Contains(err.Error(), "MIXED") {
416			t.Fatalf("mixed2 not reported as MIXED:\n%v", err)
417		}
418	
419		// Mixture 3: an ordered-looking page (height 3 positions 0 and 1) that
420		// stitches one old-branch record to one new-branch record, tagged old by
421		// its stale tip height.
422		mixed3 := oldRef
423		mixed3.Hits = []TxHit{
424			{Height: 3, BlockHash: "h3", TxID: "a", Position: 0},
425			{Height: 3, BlockHash: "j3", TxID: "q", Position: 1},
426		}
427		if err := classify(mixed3); err == nil {
428			t.Fatal("stitched hits from both branches were accepted")
429		} else if !strings.Contains(err.Error(), "MIXED") {
430			t.Fatalf("mixed3 not reported as MIXED:\n%v", err)
431		}
432	
433		// Corruption: stats belonging to no chain at all.
434		corrupt := newRef
435		corrupt.MatchedBlocks = 99
436		if err := classify(corrupt); err == nil {
437			t.Fatal("corrupt stats matching neither chain were accepted")
438		}
439	}
440	
441	// Deterministic rendezvous for the QueryTxs/Reorg overlap tests. A parked
442	// first page holds the lock with its tip already pinned; a parked
443	// continuation holds it after every pinned-range check has passed; a parked
444	// reorg has the new branch fully applied but has not returned.
445	type queryReorgHooks struct {
446		firstParked  chan struct{}
447		releaseFirst chan struct{}
448		contParked   chan struct{}
449		releaseCont  chan struct{}
450		reorgParked  chan struct{}
451		releaseReorg chan struct{}
452	
453		allowedReorgTips map[int64]bool
454		firstOnce        sync.Once
455		contOnce         sync.Once
456		reorgOnce        sync.Once
457	}
458	
459	func installQueryReorgHooks(t *testing.T, parkFirst, parkCont bool, reorgTips ...int64) *queryReorgHooks {
460		t.Helper()
461		h := &queryReorgHooks{
462			reorgParked:  make(chan struct{}),
463			releaseReorg: make(chan struct{}),
464		}
465		if parkFirst {
466			h.firstParked = make(chan struct{})
467			h.releaseFirst = make(chan struct{})
468		}
469		if parkCont {
470			h.contParked = make(chan struct{})
471			h.releaseCont = make(chan struct{})
472		}
473		if len(reorgTips) > 0 {
474			h.allowedReorgTips = map[int64]bool{}
475			for _, tip := range reorgTips {
476				h.allowedReorgTips[tip] = true
477			}
478		}
479		queryTxsHookLocked = func(from, to int64, continuation bool) {
480			switch {
481			case continuation && h.contParked != nil:
482				h.contOnce.Do(func() { close(h.contParked) })
483				<-h.releaseCont
484			case !continuation && h.firstParked != nil:
485				h.firstOnce.Do(func() { close(h.firstParked) })
486				<-h.releaseFirst
487			}
488		}
489		reorgAppliedHookLocked = func(newTip int64) {
490			if h.allowedReorgTips != nil && !h.allowedReorgTips[newTip] {
491				t.Errorf("reorg hook saw newTip=%d, want one of %v", newTip, h.allowedReorgTips)
492			}
493			h.reorgOnce.Do(func() { close(h.reorgParked) })
494			<-h.releaseReorg
495		}
496		t.Cleanup(func() {
497			queryTxsHookLocked = nil
498			reorgAppliedHookLocked = nil
499		})
500		return h
501	}
502	
503	// decodePayload exposes the signed cursor contents within the package so a
504	// test can prove which branch a cursor pins (upper height, offset, range
505	// fingerprint) without using it.
506	func decodePayload(t *testing.T, index *Index, cursor string) cursorPayload {
507		t.Helper()
508		payload, err := index.decodeCursor(cursor)
509		if err != nil {
510			t.Fatalf("cursor not decodable on its own index: %v", err)
511		}
512		return payload
513	}
514	
515	// Ordering 1: the first page is holding the lock on the complete OLD chain
516	// when the shortening reorg starts. It must finish on the old chain; once the
517	// reorg completes, its cursor is dead.
518	func TestQueryTxsFirstPageInFlightObservesCompleteOldChain(t *testing.T) {
519		index := buildQueryOldChain(t)
520		h := installQueryReorgHooks(t, true, false, 4)
521		oldChain, newChain := queryOldChainBlocks(), queryNewChainBlocks()
522	
523		result := make(chan TxPage, 1)
524		errCh := make(chan error, 1)
525		go func() {
526			page, err := index.QueryTxs(TxQuery{PageSize: 3})
527			if err != nil {
528				errCh <- err
529				return
530			}
531			result <- page
532		}()
533	
534		<-h.firstParked // query holds index.mu and has pinned tip 5
535		reorgDone := make(chan struct{})
536		go func() {
537			if _, err := index.Reorg(queryNewShortBranch()); err != nil {
538				errCh <- err
539			}
540			close(reorgDone)
541		}()
542	
543		close(h.releaseFirst) // query scans and finishes first; reorg cannot apply yet
544		var got TxPage
545		select {
546		case got = <-result:
547		case err := <-errCh:
548			t.Fatalf("concurrent call failed: %v", err)
549		}
550		want := referenceTxPage(oldChain, 3, 0)
551		if err := classifyTxPage(got, want, referenceTxPage(newChain, 3, 0),
552			referenceTxHits(oldChain), referenceTxHits(newChain)); err != nil {
553			t.Fatalf("in-flight first page did not return one complete chain:\n%v", err)
554		}
555		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
556			t.Fatalf("query holding the lock across reorg start must see old chain:\n%+v", got)
557		}
558		if !reflect.DeepEqual(got.Hits, literalOldFirstPage().Hits) {
559			t.Fatalf("old first page hits=%v, want literal old records", got.Hits)
560		}
561		if got.NextCursor == "" {
562			t.Fatal("old first page over 10 matches must carry a cursor")
563		}
564	
565		close(h.releaseReorg) // now let the parked reorg commit and return
566		<-reorgDone
567		if index.Tip != 4 {
568			t.Fatalf("tip after reorg=%d, want 4", index.Tip)
569		}
