590	// Ordering 2: the shortening reorg has fully committed (new chain installed,
591	// Reorg still holding the lock) when the first page starts. It must wait and
592	// then answer on the complete NEW chain, and its cursor must paginate the new
593	// branch to the end.
594	func TestQueryTxsFirstPageDuringCommittedReorgObservesCompleteNewChain(t *testing.T) {
595		index := buildQueryOldChain(t)
596		h := installQueryReorgHooks(t, true, false, 4)
597		oldChain, newChain := queryOldChainBlocks(), queryNewChainBlocks()
598	
599		reorgErr := make(chan error, 1)
600		go func() {
601			_, err := index.Reorg(queryNewShortBranch())
602			reorgErr <- err
603		}()
604		<-h.reorgParked // new branch applied (tip 4), Reorg still holds the lock
605	
606		result := make(chan TxPage, 1)
607		go func() {
608			page, err := index.QueryTxs(TxQuery{PageSize: 3})
609			if err != nil {
610				t.Errorf("query during reorg failed: %v", err)
611				return
612			}
613			result <- page
614		}()
615	
616		close(h.releaseReorg) // reorg returns; the first lock the query can get sees the new chain
617		if err := <-reorgErr; err != nil {
618			t.Fatalf("reorg failed: %v", err)
619		}
620		close(h.releaseFirst) // the parked first page can now scan and finish
621	
622		got := <-result
623		want := referenceTxPage(newChain, 3, 0)
624		if err := classifyTxPage(got, referenceTxPage(oldChain, 3, 0), want,
625			referenceTxHits(oldChain), referenceTxHits(newChain)); err != nil {
626			t.Fatalf("first page across reorg commit did not return one complete chain:\n%v", err)
627		}
628		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
629			t.Fatalf("query after reorg commit must see the complete new chain:\n%+v", got)
630		}
631		if !reflect.DeepEqual(got.Hits, literalNewFirstPage().Hits) {
632			t.Fatalf("new first page hits=%v, want literal new records", got.Hits)
633		}
634		if got.NextCursor == "" {
635			t.Fatal("new first page over 8 matches must carry a cursor")
636		}
637	
638		// The cursor pins the NEW branch; following it must drain exactly the new
639		// records with statistics pinned to the first page — no old-suffix leak.
640		newFingerprint := New()
641		for _, b := range newChain {
642			if err := newFingerprint.Append(b); err != nil {
643				t.Fatal(err)
644			}
645		}
646		payload := decodePayload(t, index, got.NextCursor)
647		if payload.To != 4 || payload.Off != 3 {
648			t.Fatalf("cursor pins to=%d off=%d, want 4/3", payload.To, payload.Off)
649		}
650		if payload.FP != fmt.Sprintf("%x", newFingerprint.fingerprintLocked(1, 4)) {
651			t.Fatal("cursor fingerprint does not match the complete new chain")
652		}
653	
654		query := TxQuery{PageSize: 3, Cursor: got.NextCursor}
655		var all = append([]TxHit{}, got.Hits...)
656		for pageNo := 1; ; pageNo++ {
657			page, err := index.QueryTxs(query)
658			if err != nil {
659				t.Fatalf("new-chain pagination broke at page %d: %v", pageNo, err)
660			}
661			if page.TotalMatches != 8 || page.MatchedBlocks != 4 || page.ToHeight != 4 {
662				t.Fatalf("page %d statistics drifted from the pinned first page: %+v", pageNo, page)
663			}
664			all = append(all, page.Hits...)
665			if page.NextCursor == "" {
666				break
667			}
668			query.Cursor = page.NextCursor
669		}
670		if !reflect.DeepEqual(all, referenceTxHits(newChain)) {
671			t.Fatalf("new-chain pagination=%v, want %v", all, referenceTxHits(newChain))
672		}
673	}
