				t.Fatalf("call carrying accepted content %+v failed: %v", result.block, result.err)
			}
			successes++
		default:
			requireOrdinaryRejectError(t, result.err, fmt.Sprintf("losing call %+v", result.block))
			failures++
		}
	}
	return
}

